   *
   * @example const { items } = await tools.outline(path);
   */
  function outline(path: string): Promise<{ items: Array<{ name: string; kind: "function" | "method" | "class" | "struct" | "enum" | "trait" | "impl" | "module" | "const" | "static" | "type" | "macro" | "interface" | "variable"; start_line: number; end_line: number; signature?: string; attributes?: string[]; doc?: string }> }>;

