   * - Check content *before* writing it: pass `source` and `lang` with no path, and nothing touches disk.
   *
   * @example const { ok } = await tools.parse_errors(null, candidate, lang);
   */
  function parse_errors(path: string | null, source?: string, lang?: "rust" | "javascript" | "typescript" | "python"): Promise<{ ok: boolean; errors: Array<{ line: number; message: string }> }>;

